       '{"topics": [{"id": "rt1", "title": "Neutral · everyday 1", "words": [{"id": "w001", "head": "make strides in sth", "pos": "phrase", "meaning": "make considerable progress", "examples": ["I made significant strides in my ability to communicate in English."]}, {"id": "w002", "head": "make headway", "pos": "phrase", "meaning": "make progress, especially when something is difficult", "examples": ["I finally started making headway with my speaking skills."]}, {"id": "w006", "head": "major in sth", "pos": "phrase", "meaning": "study something as your main subject at university", "examples": ["She majored in biology."]}, {"id": "w007", "head": "be built to last", "pos": "phrase", "meaning": "be made strong enough to last a long time", "examples": ["What''s wrong with Roman roads? They were built to last!"]}, {"id": "w008", "head": "stick to sth", "pos": "phrase", "meaning": "keep to something and not change it", "examples": ["We''ll stick to the classics, then."]}, {"id": "w014", "head": "get a monopoly on sth", "pos": "phrase", "meaning": "gain complete control of a market or product", "examples": ["The company managed to get a monopoly on high-speed internet in this region."]}, {"id": "w015", "head": "take over (sth)", "pos": "phrase", "meaning": "spread over or gain control of something", "examples": ["Let''s keep battling the weeds that took over our greenhouse!"]}, {"id": "w016", "head": "crumble with the slightest touch", "pos": "phrase", "meaning": "fall to pieces very easily", "examples": ["The boards crumble with the slightest touch!"]}, {"id": "w019", "head": "a playful cuff", "pos": "phrase", "meaning": "a light, joking hit with the hand", "examples": ["She gave him a playful cuff on the shoulder."]}, {"id": "w021", "head": "endearing", "pos": "", "meaning": "making people like you", "examples": ["She laughs at herself a lot, which is always endearing."]}, {"id": "w028", "head": "wilted", "pos": "", "meaning": "(of plants) soft and bending because of lac